#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string N;
    cin >> N;

    int M;
    cin >> M;

    int digit[26];
    string groups[8] = {"abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    for (int d = 0; d < 8; d++) {
        for (char c : groups[d]) {
            digit[c - 'a'] = d + 2;
        }
    }

    int ans = 0;

    for (int i = 0; i < M; i++) {
        string C;
        cin >> C;

        if (C.size() != N.size()) continue;

        bool ok = true;
        for (size_t j = 0; j < C.size(); j++) {
            if (digit[C[j] - 'a'] != N[j] - '0') {
                ok = false;
                break;
            }
        }

        if (ok) ans++;
    }

    cout << ans << '\n';
    return 0;
}
